head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vAxisType = "";
scwin.vHorizLimitCnt = 0;
window.onunload = function() {
    opener.fn_getBeforeRadioBtn("ALL");
};

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        await scwin.init();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00600_P6.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init = async function() {
    $c.cm.PanelToGroupBox(panel_Top);
    scwin.vAxisType = opener.scwin.vAxisType;
    scwin.vHorizLimitCnt = opener.scwin.vHorizLimitCnt;
    if (opener.scwin.vScrenID === "ULDFIS00600.gfm") {
        txb_IND_PTTN.setValue(opener.cmb_IND_PTTN.getValue());
        txb_ACNTG_BAS_TYP.setValue(opener.cmb_ACNTG_BAS_TYP.getValue());
        txb_INDVDL_CONN_TP.setValue(opener.cmb_INDVDL_CONN_TP.getValue());
    } else if (opener.scwin.vScrenID === "ULDFIS00600_P2.gfm" || opener.scwin.vScrenID === "ULDFIS00600_P5.gfm") {
        txb_IND_PTTN.setValue(opener.txb_IND_PTTN.getValue());
        txb_ACNTG_BAS_TYP.setValue(opener.txb_ACNTG_BAS_TYP.getValue());
        txb_INDVDL_CONN_TP.setValue(opener.txb_INDVDL_CONN_TP.getValue());
    }
    scwin.initDs();

    // 계정유형 조회
    await scwin.getDtsAccntPttn();

    // 조회
    await scwin.search();

    // 이전에 선택된 항목을 화면에 display
    scwin.displayBefItem();

    // chb_COL_YEAR 체크박스 제어
    await scwin.ctrlChbCOLYEAR();
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_Acnt_OnLoadError
 * @description dts_Acnt 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Acnt_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_Acnt);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00600_P6.dts_Acnt_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_Acnt_OnLoadCompleted
 * @description dts_Acnt 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Acnt_OnLoadCompleted = async function(rowcount) {
    try {
        if (dts_Acnt.errorMsg) {
            await $c.win.alert(dts_Acnt.errorMsg);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00600_P6.dts_Acnt_OnLoadCompleted" });
    }
};

