 * @description txb_ACCNT_NM 키 입력 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.txb_ACCNT_NM_onkeydown = async function() {
    try {
        // 기업집단검색 팝업 오픈
        if (event.keyCode === 13) {
            await scwin.search();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00600_P6.txb_ACCNT_NM_onkeydown" });
