    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00600_P6.cmb_ACCNT_PTTN_onselchange" });
    }
};

/**
 * @method
 * @name trv_Acnt_OnDblClick
 * @description trv_Acnt 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.trv_Acnt_OnDblClick = function() {
    try {
        const selLv = trv_Acnt.getSelectedNode().depth;
        const selIndex = trv_Acnt.getSelectedIndex() + 1;
        const selChecked = trv_Acnt.findNodeByIndex(trv_Acnt.getSelectedIndex(), false).checked;
        for (let i = selIndex; i <= dts_Acnt.getRowCount(); i++) {
            const checkLv = dts_Acnt.getCellData(i, "LV");
            if (checkLv <= selLv) return;
            trv_Acnt.checkByIndex(i, (selChecked) ? true : false); // 체크박스 언체크

        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDFIS00600_P6.trv_Acnt_OnDblClick" });
    }
};

/**
 * @method
 * @name btn_init_onclick
 * @description 「초기화」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_init_onclick = async function() {
    try {
        await scwin.reset();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00600_P6.btn_init_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name getDtsAccntPttn
 * @description 재무유형 조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.getDtsAccntPttn = async function() {
    const sbmOptions = {
        id : "sbm_dts_AccntPttn",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_AccntPttn=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name getYear
 * @description 년도콤보 세팅. 년도구하기
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.getYear = async function() {
    const sbmOptions = {
        id : "sbm_dts_Year",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_Year=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name search
 * @description 조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    // 데이터셋 초기화
    scwin.clearDs();

    // 조회조건 필수 체크.
    if (!scwin.chkValid()) {
        return;
    }

    // Lodaing~~~ 표시
    const sbmOptions = {
        id : "sbm_dts_Acnt",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_Acnt=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name displayBefItem
 * @description 이미 선택되어있는 항목을 화면이 open할때 화면에 display한다.
 * @returns {void}
 * @hidden N
 */
scwin.displayBefItem = function() {
    trv_SelectedAcnt.ReDraw = false;
    let tmpDs = opener.dts_Fz531;
    dts_SelectAcnt.setBroadcast(false);
    for (let nRow = 1; nRow <= tmpDs.getRowCount(); nRow++) {
        // AXIS_TYP 2 가로, 3 세로 / ITEM_TYP  0 년도, 1 계정, 3 회사
        // if( (tmpDs.NameString(nRow, "AXIS_TYP") == "2" || tmpDs.NameString(nRow, "AXIS_TYP") == "3") && tmpDs.NameString(nRow, "ITEM_TYP") == "1" ){
        if (scwin.vAxisType === tmpDs.getCellData(nRow, "AXIS_TYP") && tmpDs.getCellData(nRow, "ITEM_TYP") === "1") {
            dts_SelectAcnt.insertRow();
            let nIdx = dts_SelectAcnt.getRowPosition();
            dts_SelectAcnt.setCellData(nIdx, "LV", "2");
            dts_SelectAcnt.setCellData(nIdx, "ACCNT_CD", tmpDs.getCellData(nRow, "ITEM_CD"));
            dts_SelectAcnt.setCellData(nIdx, "ACCNT_NM", $c.stf.trim(tmpDs.getCellData(nRow, "ITEM_NM")));
            dts_SelectAcnt.setCellData(nIdx, "COL_YEAR", tmpDs.getCellData(nRow, "COL_YEAR"));
        }
    }
    dts_SelectAcnt.setBroadcast(true, true); // end for

    trv_SelectedAcnt.ReDraw = true;
};

/**
 * @method
 * @name initDs
 * @description 데이터셋 초기화.
 * @returns {void}
 * @hidden N
 */
scwin.initDs = function() {

    // dts_SelectAcnt.setDataHeader();
    // dts_SelectAcnt.AddRow();
    // var nRow = dts_SelectAcnt.RowPosition;
    // dts_SelectAcnt.NameString(nRow, "LV") = "1";
    // dts_SelectAcnt.NameString(nRow, "ACCNT_NM") = "선택된 계정"; // W-Craft 주석처리 및 필요시 asis 파라미터 확인

};

/**
 * @method
 * @name clearDs
 * @description 데이터셋 clear.
 * @returns {void}
 * @hidden N
 */
scwin.clearDs = function() {
    dts_Acnt.removeAll();
};

/**
 * @method
 * @name chkValid
 * @description 조회조건 유효성 체크
 * @returns {void}
 * @hidden N
 */
scwin.chkValid = function() {
    return true;
};

/**
 * @method
 * @name setParam
 * @description 선택된 값을 오프너에 전달한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setParam = async function() {
    if (dts_SelectAcnt.getRowCount() < 1) {
        return;
    }
    const arrPar = new Array();
    for (let nRow = 1; nRow <= dts_SelectAcnt.getRowCount(); nRow++) {
        const sItemCd = dts_SelectAcnt.getCellData(nRow, "ACCNT_CD");
        const sItemNM = dts_SelectAcnt.getCellData(nRow, "ACCNT_NM");
        const sItemTyp = "1"; // 0:년도, 1:계정, 3:회사
        const sAxisTyp = scwin.vAxisType; // AXIS_TYP  1:기준, 2: 가로, 3:세로
        const sColYear = dts_SelectAcnt.getCellData(nRow, "COL_YEAR"); // COL_YEAR

        if (sItemCd !== "") {
            arrPar[nRow - 1] = {
                ITEM_CD: sItemCd,
                ITEM_NM: sItemNM,
                ITEM_TYP: sItemTyp,
                AXIS_TYP: sAxisTyp,
                COL_YEAR: sColYear
            };
        }
    }
    $c.frame.path("../").fn_SetAxisInfo(arrPar);
    await $c.win.closePopup();
};

/**
 * @method
 * @name reset
 * @description reset 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.reset = async function() {
    trv_SelectedAcnt.ClearAll();
    dts_SelectAcnt.removeAll();
    await scwin.getYear();
    chb_COL_YEAR.setDisabled("");
    chb_COL_YEAR.setValue(1);
    cmb_COL_YEAR.setDisabled(false);
    cmb_COL_YEAR.setSelectedIndex(0);
    // fn_SelectAll();
    // fn_RmSelected();

};

/**
 * @method
 * @name rmSelected
 * @description 선택제거
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.rmSelected = async function() {
    trv_SelectedAcnt.ReDraw = false;
    dts_SelectAcnt.setBroadcast(false);
    for (let nRow = dts_SelectAcnt.getRowCount(); nRow >= 1; nRow--) {
        if (trv_SelectedAcnt.findNodeByIndex(nRow, false).checked) {
            dts_SelectAcnt.removeRow(nRow);
        }
    }
    dts_SelectAcnt.setBroadcast(true, true);
    if (dts_SelectAcnt.getRowCount() === 0) {
        await scwin.getYear();
        chb_COL_YEAR.setDisabled("");
        chb_COL_YEAR.setValue(1);
        cmb_COL_YEAR.setDisabled(false);
        cmb_COL_YEAR.setSelectedIndex(0);
    }
    trv_SelectedAcnt.ReDraw = true;
};

/**
 * @method
 * @name selected
 * @description 선택
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.selected = async function() {
    // dts_SelectAcnt.ClearData();
    trv_SelectedAcnt.ReDraw = false;

    // 가로 세팅이면 갯수 체크 :  2 가로, 3 세로
    if (scwin.vAxisType === "2") {
        // 선택된것 갯수
        let nSelectCnt = dts_SelectAcnt.getRowCount();
        for (let nRow = 1; nRow <= dts_Acnt.getRowCount(); nRow++) {
            if (trv_Acnt.findNodeByIndex(nRow, false).checked) {
                nSelectCnt++;
            }
        }
        // 갯수체크
        if (nSelectCnt > scwin.vHorizLimitCnt) {
            await $c.win.alert("선택된 가로항목이 10개를 초과합니다.");
            return;
        }
    }
    const chkYear = chb_COL_YEAR.getValue();
    const valYear = cmb_COL_YEAR.getValue();
    dts_SelectAcnt.setBroadcast(false);
    for (let nRow = 1; nRow <= dts_Acnt.getRowCount(); nRow++) {
        if (trv_Acnt.findNodeByIndex(nRow, false).checked) {
            // 중복 체크.
            if (chkYear === "Y") {
                let bDup = false;
                const sTmp1 = dts_Acnt.getCellData(nRow, "ACCNT_CD") + valYear;
                for (let nIdx = 1; nIdx <= dts_SelectAcnt.getRowCount(); nIdx++) {
                    const sTmp2 = dts_SelectAcnt.getCellData(nIdx, "ACCNT_CD") + dts_SelectAcnt.getCellData(nIdx, "COL_YEAR");
                    if (sTmp1 === sTmp2) {
                        bDup = true;
                        continue;
                    }
                }
                if (bDup) {
                    trv_Acnt.checkByIndex(nRow, false); // 체크박스 언체크
                    continue;
                }
            } else {
                let nTmpIdx1 = $c.cp.getNameValueRow(dts_SelectAcnt, "ACCNT_CD", dts_Acnt.getCellData(nRow, "ACCNT_CD"));
                if (nTmpIdx1 >= 1) {
                    trv_Acnt.checkByIndex(nRow, false); // 체크박스 언체크
                    continue;
                }

                // ********************************************************************
                // [WebSquare 전환 추가] 원본 소스와 비교 필요
                //
                // ********************************************************************

            }
            dts_SelectAcnt.insertRow();
            let nIdx = dts_SelectAcnt.getRowPosition();
            dts_SelectAcnt.setCellData(nIdx, "LV", "2");
            dts_SelectAcnt.setCellData(nIdx, "ACCNT_CD", dts_Acnt.getCellData(nRow, "ACCNT_PTTN") + dts_Acnt.getCellData(nRow, "ACCNT_CD")); /*ORG SRC: dts_SelectAcnt.NameString(nIdx, "ACCNT_NM") = chkYear == "Y" ? valYear + " " + dts_Acnt.NameString(nRow, "ACCNT_NM") : dts_Acnt.NameString(nRow, "ACCNT_NM");*/ X = chkYear === "Y" ? valYear + " " + dts_Acnt.getCellData(nRow, "ACCNT_NM") : dts_Acnt.getCellData(nRow, "ACCNT_NM"); /*ORG SRC: dts_SelectAcnt.NameString(nIdx, "COL_YEAR") = chkYear == "Y" ? valYear : "0000";*/ X = chkYear === "Y" ? valYear : "0000";
            trv_Acnt.checkByIndex(nRow, false); // 체크박스 언체크

        }
    }
    dts_SelectAcnt.setBroadcast(true, true);
    trv_SelectedAcnt.ReDraw = true;
};

/**
 * @method
 * @name chbCOLYEAROnClick
 * @description 체크박스 온클릭
 * @param {*} pClearData pClearData
 * @returns {void}
 * @hidden N
 */
scwin.chbCOLYEAROnClick = function(pClearData) {
    if (pClearData) {
        dts_SelectAcnt.removeAll();
    }
    if (chb_COL_YEAR.getValue() === "Y") {
        cmb_COL_YEAR.setDisabled(false);
        cmb_COL_YEAR.setSelectedIndex(0);
    } else {
        cmb_COL_YEAR.setDisabled(true);
        cmb_COL_YEAR.setSelectedIndex(-1);
    }
};

/**
 * @method
 * @name ctrlChbCOLYEAR
 * @description 가로항목인 경우만 선택 가능. 잘못봤다 세로도 선택가능.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ctrlChbCOLYEAR = async function() {
    // 기준이 선택되어있다면 비활성.
    // 어딘가에서 년도가 선택되었다면 비활성.
    // 어딘가에서 이미 체크가 되었다면 비활성. => COL_YEAR 이 0000이 아닌게 존재한다.
    let tmpDs = opener.dts_Fz531;

    // 어딘가에서 이미 체크가 되었다면 비활성. => COL_YEAR 이 0000이 아닌게 존재한다.
    let bChecked = false;
    for (let nRow = 1; nRow <= tmpDs.getRowCount(); nRow++) {
        if (tmpDs.getCellData(nRow, "COL_YEAR") !== "0000") {
            bChecked = true;
            break;
        }
    }

    // 기준이 선택되어있다면 비활성.
    // 어딘가에서 년도가 선택되었다면 비활성.
    let nTmpIdx1 = tmpDs.NameValueRow("AXIS_TYP", "1");
    const nTmpIdx2 = tmpDs.NameValueRow("ITEM_TYP", "0"); // ITEM_TYP  0 년도, 1 계정, 3 회사
    if (nTmpIdx1 < 1 && nTmpIdx2 < 1 && !bChecked) {
        // 년도콤보세팅
        await scwin.getYear();
        chb_COL_YEAR.setDisabled("");
        chb_COL_YEAR.setValue(1);
        scwin.chbCOLYEAROnClick();
    }
};
